window.__finlexDocLoaded(10060,{"id":10060,"articles":[{"id":1000161,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Establishes the five fundamental principles (integrity, objectivity, professional competence and due care, confidentiality, professional behavior) and the conceptual framework for all professional accountants in business (Part 2) and public practice (Part 3), incorporating 2026 external expert and sustainability reporting revisions.","seq":0},{"id":1000162,"no":"IESBA Sec 110–390","heading":"Five Fundamental Principles, Threats & 2026 External Expert Rules","text":"• Five Fundamental Principles (Section 110): Integrity, Objectivity, Professional Competence and Due Care, Confidentiality, and Professional Behavior.\n• Five Threat Categories (Section 120): Self-interest, Self-review, Advocacy, Familiarity, and Intimidation — addressed by eliminating circumstances, applying safeguards, or declining/ending the engagement.\n• NOCLAR (Sections 260 & 360): structured response framework for Non-Compliance with Laws and Regulations.\n• 2026 Handbook Additions (effective 15 Dec 2026): new Section 290 (PAIBs) and Section 390 (PAPPs) governing ethical evaluation when using the work of an external expert, plus sustainability reporting ethics revisions.","seq":1},{"id":1000163,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IESBA 2026 Handbook): https://www.ethicsboard.org/publications/2026-handbook-international-code-ethics-professional-accountants\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.\n2026 Handbook Volume: Volume 1 (Parts 1–3, Part 4A & Part 4B)\nOfficial Free PDF (Vol. 1): https://ifacweb.blob.core.windows.net/publicfiles/2026-09/2026-IESBA-HB-Volume-1.pdf\nLocal Private Full-Text Import: Run `python3 scripts/import_private_intl_pdfs.py --download-iesba` (or place the PDF in local_pdfs/).","seq":2}]});
